INSERT INTO mk_referral_fulfillment_current(tenant_id,reward_id,provider_id,provider_revision,delivery_state,compensation_state,business_digest,success_digest,terminal_digest,created_at,updated_at)
  VALUES(#{tenant},#{reward},#{provider},#{providerRevision},#{delivery},#{compensation},#{digest},#{success},#{terminal},#{now},#{now})
  ON DUPLICATE KEY UPDATE provider_revision=#{providerRevision},delivery_state=#{delivery},compensation_state=#{compensation},business_digest=#{digest},success_digest=#{success},terminal_digest=#{terminal},updated_at=#{now}
